ALTER TABLE public.mkt_staff_specialties ADD COLUMN IF NOT EXISTS eligibility_enforced boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.mkt_staff_specialties.eligibility_enforced IS 'New/reactivated tasks require live Marketing membership; old rows await confirmed cutover.';
CREATE UNIQUE INDEX IF NOT EXISTS app_roles_stable_code_unique ON public.app_roles(role_code) WHERE role_code IS NOT NULL;
CREATE OR REPLACE FUNCTION private.org_marketing_eligible(u uuid,c jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_active(u) AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(c->'memberships','[]')) m JOIN LATERAL jsonb_array_elements(coalesce(c->'titles','[]')) t ON t->>'id'=m->>'title_id' WHERE m->>'user_id'=u::text AND private.base_valid_at(m) AND coalesce(m->>'status','active')='active' AND coalesce((t->>'active')::boolean,false) AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(c->'units','[]')) b WHERE b->>'kind'='block' AND (b->>'id'='b5e00000-0000-4000-8000-000000000001' OR b->>'code'='marketing') AND coalesce((b->>'active')::boolean,true) AND private.base_role_unit_contains(c,b->>'id',m->>'unit_id'))) $$;
CREATE OR REPLACE FUNCTION private.mkt_task_assignment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.state='active' AND EXISTS(SELECT 1 FROM mkt_specialties s JOIN app_roles r ON r.id=s.role_id WHERE s.id=NEW.specialty_id AND r.role_kind='marketing_task') THEN IF TG_OP='INSERT' OR OLD.state IS DISTINCT FROM NEW.state OR OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.specialty_id IS DISTINCT FROM NEW.specialty_id THEN IF NOT private.org_marketing_eligible(NEW.user_id,private.base_config()) THEN RAISE EXCEPTION 'Chỉ nhân sự có bổ nhiệm Marketing hiệu lực được cấp nhiệm vụ.' USING ERRCODE='42501'; END IF; NEW.eligibility_enforced:=true; ELSIF OLD.eligibility_enforced THEN NEW.eligibility_enforced:=true; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION private.mkt_specialty_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('id','mkt:'||m.specialty_id||':'||p,'permission',p,'effect','ALLOW','scope','own','active',true,'source_kind','marketing_specialty','source_id',m.specialty_id,'source_name',s.name,'role_id',r.id,'legacy',NOT m.eligibility_enforced)),'[]'::jsonb) FROM mkt_staff_specialties m JOIN mkt_specialties s ON s.id=m.specialty_id AND s.active JOIN app_roles r ON r.id=s.role_id CROSS JOIN LATERAL unnest(r.permissions) p WHERE m.user_id=u AND m.state='active' AND private.is_active(u) AND private.mkt_specialty_permission_ready(p) AND (r.role_kind<>'marketing_task' OR NOT m.eligibility_enforced OR private.org_marketing_eligible(u,c)) $$;
DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('private.org_role_rules(uuid,jsonb)'::regprocedure) INTO d; d:=replace(d,'FUNCTION private.org_role_rules(','FUNCTION private.slot_previous_role_rules('); d:=replace(d,'WHERE private.is_active(u)','WHERE nullif(m->>''slot_id'','''') IS NULL AND private.is_active(u)'); EXECUTE d; END $patch$;
CREATE OR REPLACE FUNCTION private.org_slot_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',(m->>'id')||':'||r.id||':'||p,'permission',p,'effect','ALLOW','scope','native','active',true,'source_kind','appointment_role','source_id',m->>'id','source_name',r.name,'role_id',r.id,'unit_id',m->>'unit_id','slot_id',s->>'id','starts_at',m->>'starts_at','ends_at',m->>'ends_at','legacy',false)),'[]'::jsonb) FROM jsonb_array_elements(coalesce(c->'memberships','[]')) m JOIN LATERAL jsonb_array_elements(coalesce(c->'position_slots','[]')) s ON s->>'id'=m->>'slot_id' AND s->>'title_id'=m->>'title_id' AND s->>'unit_id'=m->>'unit_id' JOIN LATERAL jsonb_array_elements(coalesce(c->'titles','[]')) t ON t->>'id'=m->>'title_id' JOIN app_roles r ON r.id=s->>'role_id' AND r.role_kind='position' AND r.catalog_state='standard' AND NOT r.is_system CROSS JOIN LATERAL unnest(r.permissions) p WHERE private.is_active(u) AND m->>'user_id'=u::text AND private.base_valid_at(m) AND coalesce(m->>'status','active')='active' AND coalesce((s->>'active')::boolean,false) AND coalesce((t->>'active')::boolean,false) AND private.org_role_permission_ready(p) $$;
CREATE OR REPLACE FUNCTION private.org_role_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.slot_previous_role_rules(u,c)||private.org_slot_rules(u,c) $$;
DO $patch$ DECLARE d text; needle text; BEGIN SELECT pg_get_functiondef('private.base_config()'::regprocedure) INTO d; IF strpos(d,'''position_slots''')=0 THEN d:=replace(d,'''role_links'',','''position_slots'',private.org_config()->''position_slots'',''role_links'','); END IF; EXECUTE d; SELECT pg_get_functiondef('private.org_commands(jsonb)'::regprocedure) INTO d; needle:='IF NOT EXISTS(SELECT 1 FROM org_position_slots s JOIN base_title_role_links l ON l.title_id=old_.title_id AND l.role_id=s.role_id WHERE s.id=v->>''slot_id'' AND s.unit_id=old_.unit_id AND s.title_id=old_.title_id) OR (SELECT count(*) FROM base_title_role_links WHERE title_id=old_.title_id)<>1 THEN RAISE EXCEPTION ''Chuyển ô chỉ giữ đúng Role hiện tại; mapping khác cần đối chiếu quyền.''; END IF;'; IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'Mapping contract changed'; END IF; EXECUTE replace(d,needle,'IF NOT EXISTS(SELECT 1 FROM org_position_slots s WHERE s.id=v->>''slot_id'' AND s.unit_id=old_.unit_id AND s.title_id=old_.title_id AND s.role_id=v->>''reviewed_role'') THEN RAISE EXCEPTION ''Mapping phải xem trước đúng Role, chức danh và đơn vị.''; END IF;'); END $patch$;
CREATE OR REPLACE FUNCTION private.role_new_empty_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT NEW.is_system AND NEW.role_kind='position' AND coalesce(cardinality(NEW.permissions),0)>0 THEN RAISE EXCEPTION 'Role vị trí mới phải có permissions=[]; cấu hình quyền sau khi tạo.' USING ERRCODE='42501'; END IF; IF NEW.role_code IS NULL THEN NEW.role_code:=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER role_new_empty_guard BEFORE INSERT ON public.app_roles FOR EACH ROW EXECUTE FUNCTION private.role_new_empty_guard();
CREATE OR REPLACE FUNCTION private.role_source_rows(c jsonb) RETURNS TABLE(user_id uuid,role_id text,source_kind text,source_id text,unit_id text,legacy boolean,eligible boolean,scope text,permissions text[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH members AS (SELECT m FROM jsonb_array_elements(coalesce(c->'memberships','[]')) m WHERE private.base_valid_at(m) AND coalesce(m->>'status','active')='active'), links AS (SELECT l FROM jsonb_array_elements(coalesce(c->'role_links','[]')) l), slots AS (SELECT s FROM jsonb_array_elements(coalesce(c->'position_slots','[]')) s) SELECT (m->>'user_id')::uuid,r.id,'slot',m->>'id',m->>'unit_id',false,true,'native',ARRAY(SELECT p FROM unnest(r.permissions) p WHERE private.org_role_permission_ready(p)) FROM members JOIN slots ON s->>'id'=m->>'slot_id' AND s->>'unit_id'=m->>'unit_id' AND s->>'title_id'=m->>'title_id' JOIN app_roles r ON r.id=s->>'role_id' AND r.role_kind='position' AND r.catalog_state='standard' WHERE coalesce((s->>'active')::boolean,false) AND private.is_active((m->>'user_id')::uuid) UNION ALL SELECT (m->>'user_id')::uuid,r.id,'title_legacy',m->>'id',m->>'unit_id',true,true,'native',ARRAY(SELECT p FROM jsonb_array_elements_text(coalesce(l->'enabled_permissions','[]')) p WHERE p=ANY(r.permissions) AND private.org_role_permission_ready(p)) FROM members JOIN links ON l->>'title_id'=m->>'title_id' JOIN app_roles r ON r.id=l->>'role_id' WHERE nullif(m->>'slot_id','') IS NULL AND l->>'scope_kind'='own' AND l->>'permission_signature'=md5(coalesce(r.permissions,'{}')::text) AND private.is_active((m->>'user_id')::uuid) UNION ALL SELECT m.user_id,r.id,CASE WHEN r.role_kind='marketing_task' THEN 'task' ELSE 'specialty' END,m.specialty_id,NULL,NOT m.eligibility_enforced,r.role_kind<>'marketing_task' OR private.org_marketing_eligible(m.user_id,c),'own',ARRAY(SELECT p FROM unnest(r.permissions) p WHERE private.mkt_specialty_permission_ready(p)) FROM mkt_staff_specialties m JOIN mkt_specialties s ON s.id=m.specialty_id AND s.active JOIN app_roles r ON r.id=s.role_id WHERE m.state='active' AND private.is_active(m.user_id) AND (r.role_kind<>'marketing_task' OR NOT m.eligibility_enforced OR private.org_marketing_eligible(m.user_id,c)) UNION ALL SELECT ur.user_id,r.id,'direct',r.id,NULL,true,true,'native',r.permissions FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id WHERE private.is_active(ur.user_id) $$;
CREATE OR REPLACE FUNCTION public.role_actual_sources(_target uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb; e jsonb; BEGIN IF NOT private.is_active(auth.uid()) OR NOT (auth.uid()=_target OR private.is_super_admin(auth.uid()) OR private.has_permission(auth.uid(),'settings.user_view') OR private.has_permission(auth.uid(),'settings.user_custom_perm')) THEN RAISE EXCEPTION 'Không có quyền xem nguồn Role.' USING ERRCODE='42501'; END IF; c:=private.base_config(); e:=private.base_effective(_target,c); RETURN jsonb_build_object('sources',(SELECT coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('role_name',r.name,'unit_name',u.name) ORDER BY s.source_kind,s.source_id),'[]') FROM private.role_source_rows(c) s JOIN app_roles r ON r.id=s.role_id LEFT JOIN org_units u ON u.id=s.unit_id WHERE s.user_id=_target),'effective',(SELECT coalesce(jsonb_agg(p->>'key'),'[]') FROM jsonb_array_elements(e) p WHERE (p->>'allowed')::boolean),'legacy_paths',to_jsonb(ARRAY(SELECT DISTINCT source_kind FROM private.role_source_rows(c) WHERE user_id=_target AND legacy)||CASE WHEN EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_target AND use_custom) THEN ARRAY['override'] ELSE ARRAY[]::text[] END||CASE WHEN EXISTS(SELECT 1 FROM biz_appointments WHERE user_id=_target) THEN ARRAY['biz_appointments (workflow riêng)'] ELSE ARRAY[]::text[] END)); END $$;
REVOKE ALL ON FUNCTION public.role_actual_sources(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.role_actual_sources(uuid) TO authenticated;
REVOKE ALL ON FUNCTION private.org_slot_rules(uuid,jsonb),private.slot_previous_role_rules(uuid,jsonb),private.role_source_rows(jsonb),private.role_new_empty_guard() FROM PUBLIC,anon,authenticated,service_role;
DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.role_catalog_read()'::regprocedure) INTO d; d:=replace(d,$old$WHERE a.slot_id IS NULL AND a.status='active' AND (a.ends_at IS NULL OR a.ends_at>now())$old$,$new$WHERE a.slot_id IS NULL AND a.status<>'cancelled'$new$); d:=replace(d,$old$'category',a.category)$old$,$new$'category',a.category,'status',a.status)$new$); EXECUTE replace(d,'FUNCTION public.role_catalog_read(','FUNCTION private.slot_catalog_previous_read('); END $patch$;
CREATE OR REPLACE FUNCTION public.role_catalog_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d jsonb; counts jsonb; BEGIN d:=private.slot_catalog_previous_read(); SELECT coalesce(jsonb_object_agg(role_id,stats),'{}') INTO counts FROM (SELECT role_id,jsonb_build_object('total',count(DISTINCT user_id),'slots',count(DISTINCT user_id) FILTER(WHERE source_kind='slot'),'tasks',count(DISTINCT user_id) FILTER(WHERE source_kind IN ('task','specialty')),'direct',count(DISTINCT user_id) FILTER(WHERE source_kind='direct'),'legacy',count(DISTINCT user_id) FILTER(WHERE source_kind='title_legacy')) stats FROM private.role_source_rows(private.base_config()) GROUP BY role_id) x; RETURN jsonb_set(d,'{roles}',(SELECT coalesce(jsonb_agg(r||jsonb_build_object('receivers',coalesce((counts->(r->>'id')->>'total')::int,0),'receiver_counts',coalesce(counts->(r->>'id'),'{}'))),'[]') FROM jsonb_array_elements(d->'roles') r)); END $$;
REVOKE ALL ON FUNCTION private.slot_catalog_previous_read() FROM PUBLIC,anon,authenticated,service_role;
DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.account_org_summary(uuid)'::regprocedure) INTO d; EXECUTE replace(d,'FUNCTION public.account_org_summary(','FUNCTION private.slot_account_previous_summary('); END $patch$;
CREATE OR REPLACE FUNCTION public.account_org_summary(_target uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d jsonb; BEGIN d:=private.slot_account_previous_summary(_target); RETURN jsonb_set(d,'{roles}',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name)),'[]') FROM (SELECT DISTINCT r.id,r.name FROM private.role_source_rows(private.base_config()) s JOIN app_roles r ON r.id=s.role_id WHERE s.user_id=_target AND cardinality(s.permissions)>0) x)); END $$;
REVOKE ALL ON FUNCTION private.slot_account_previous_summary(uuid) FROM PUBLIC,anon,authenticated,service_role;